DROP TABLE IF EXISTS `tblentrydetails`;
CREATE TABLE IF NOT EXISTS `tblentrydetails` (
  `EntryID` int NOT NULL AUTO_INCREMENT,
  `Date` date DEFAULT NULL,
  `Time` time DEFAULT NULL,
  `Year` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Month` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Day` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `Category` text COLLATE utf8mb4_general_ci,
  `EntryText` text COLLATE utf8mb4_general_ci,
  `Amount` float DEFAULT NULL,
  `DescribeText` text COLLATE utf8mb4_general_ci,
  `Type` text COLLATE utf8mb4_general_ci,
  `FilePath` text COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`EntryID`)
) ENGINE=InnoDB AUTO_INCREMENT=466 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

